import base64,datetime,hashlib,json,os,pathlib,subprocess,sys,time,urllib.request
MODE=sys.argv[1]
assert MODE in ('apply','verify','rollback'),'mode required'
T=json.loads(base64.b64decode(''))
B=pathlib.Path('/opt/flash-ticket-obs/pinned')
C='flash-ticket-obs-grafana'
FIELDS=['uid','title','panels','templating','time','links','tags']
def now(): return datetime.datetime.now(datetime.timezone.utc).isoformat()
def emit(d): print(json.dumps(d,ensure_ascii=False),flush=True)
def digest(b): return {'sha256':hashlib.sha256(b).hexdigest(),'bytes':len(b)}
def stop():
 assert not pathlib.Path('/home/ubuntu/rca-dieu-phoi/STOP').exists(),'STOP remote'
def inspect(): return json.loads(subprocess.check_output(['docker','inspect',C]))[0]
def machine():
 d=inspect(); return {'started_at':d['State']['StartedAt'],'restart_count':d['RestartCount'],'status':d['State']['Status']}
def inventory():
 return {str(p):digest(p.read_bytes()) for p in [B/'compose.json',*sorted((B/'provisioning').rglob('*'))] if p.is_file()}
stop()
ins=inspect()
env=dict(x.split('=',1) for x in ins['Config']['Env'] if '=' in x)
auth=base64.b64encode((env.get('GF_SECURITY_ADMIN_USER','admin')+':'+env['GF_SECURITY_ADMIN_PASSWORD']).encode()).decode()
def api(uid):
 req=urllib.request.Request('http://10.0.0.215:3000/api/dashboards/uid/'+uid,headers={'Authorization':'Basic '+auth})
 with urllib.request.urlopen(req,timeout=15) as res: return {'http':res.status,'data':json.load(res)}
def checked_file(t,which):
 p=pathlib.Path(t['path'])
 assert p.resolve().is_relative_to((B/'provisioning/dashboards').resolve()) and not p.is_symlink(),'target path'
 b=p.read_bytes(); assert digest(b)==t[which],('file pin',t['name'],which)
 return b
def same_loaded(a,d): return all(a['data']['dashboard'].get(k)==d.get(k) for k in FIELDS)
def get_pin(a): return digest(json.dumps({k:a['data']['dashboard'].get(k) for k in FIELDS},ensure_ascii=False,sort_keys=True,separators=(',',':')).encode())
initial='before' if MODE=='apply' else 'after'
final='before' if MODE=='rollback' else 'after'
inv_before=inventory(); machine_before=machine(); fresh_get={}
for t in T:
 stop(); b=checked_file(t,initial); a=api(t['uid'])
 assert same_loaded(a,json.loads(b)),('GET/file before',t['name'])
 fresh_get[t['name']]={'path':t['path'],**digest(b),'api':a,'get_source_projection':get_pin(a),'get_matches_file':True}
 for w in ('before','after'): assert digest(base64.b64decode(t[w+'_base64']))==t[w],('payload pin',t['name'],w)
 old=json.loads(base64.b64decode(t['before_base64'])); new=json.loads(base64.b64decode(t['after_base64']))
 panel=next(p for p in new['panels'] if p['id']==5); del panel['description']
 assert old==new,('description-only',t['name'])
emit({'event':'before','utc':now(),'mode':MODE,'targets':fresh_get,'files':inv_before,'machine':machine_before,'stop':False})
if MODE!='verify':
 for t in T:
  stop(); checked_file(t,initial)
  b=base64.b64decode(t[final+'_base64'])
  with pathlib.Path(t['path']).open('r+b') as f:
   assert digest(f.read())==t[initial],('handle pin',t['name'])
   f.seek(0); assert f.write(b)==len(b); f.truncate(len(b)); f.flush(); os.fsync(f.fileno())
  checked_file(t,final)
  emit({'event':'wrote','utc':now(),'path':t['path'],'before':t[initial],'after':t[final],'only_existing_file_written':True})
loaded={}
for attempt in range(1,4):
 stop(); loaded={}
 for t in T:
  b=checked_file(t,final); a=api(t['uid']); loaded[t['name']]={'path':t['path'],**digest(b),'api':a,'get_source_projection':get_pin(a),'get_matches_file':same_loaded(a,json.loads(b))}
 ready=all(x['get_matches_file'] for x in loaded.values())
 emit({'event':'ready','utc':now(),'attempt':attempt,'ready':ready})
 if ready: break
 if attempt<3: time.sleep(10)
assert ready,'provisioning not ready after three observations'
inv_after=inventory(); machine_after=machine(); changed=[p for p in sorted(set(inv_before)|set(inv_after)) if inv_before.get(p)!=inv_after.get(p)]
expected=[] if MODE=='verify' else sorted(t['path'] for t in T)
assert changed==expected,('unexpected inventory changes',changed)
assert machine_before==machine_after,'machine restarted or changed'
emit({'event':'done','utc':now(),'mode':MODE,'targets':loaded,'files':inv_after,'changed_files':changed,'machine_before':machine_before,'machine_after':machine_after,'restart':False,'stop':False})
